alter table users add column permissions jsonb not null default '{}',add column active boolean not null default true;
alter table conversations add column status text not null default 'open' check(status in ('open','closed')),add column created_at timestamptz not null default now(),add column closed_at timestamptz,add column close_reason text,add column close_category text;
alter table messages add column filename text;
create index messages_external_lookup on messages(tenant_id,conversation_id,ext_id) where ext_id is not null;
create table service_events(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,conversation_id int references conversations,actor_id int references users,team_id int references teams,type text not null,data jsonb not null default '{}',at timestamptz not null default now());
create table labels(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,color text not null default '#6d5ce7',active bool default true,unique(tenant_id,name));
create table field_definitions(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,kind text not null check(kind in ('text','integer','decimal','date','datetime','url','boolean','select')),options jsonb default '[]',scope text not null default 'contact' check(scope in ('contact','opportunity')),active bool default true);
create table contact_notes(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,contact_id int references contacts,conversation_id int references conversations,author_id int references users,body text not null,at timestamptz default now());
alter table contacts add column labels int[] not null default '{}',add column custom_fields jsonb not null default '{}';
create table media_assets(file text primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,owner_id int references users,mime text,name text,created_at timestamptz default now());
create table crm_boards(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,name text not null,code text not null,description text not null default '',kind text not null default 'sales' check(kind in ('sales','management')),team_ids int[] default '{}',manager_ids int[] default '{}',visibility text not null default 'individual' check(visibility in ('individual','team')),allow_restricted bool default false,inactivity_days int check(inactivity_days between 1 and 3650),celebrate bool default false,sound bool default false,labels int[] default '{}',fields jsonb default '[]',created_by int references users,created_at timestamptz default now());
create table crm_stages(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,board_id int not null references crm_boards on delete cascade,name text not null,color text default '#6d5ce7',pos int not null,final bool not null default false);
create table crm_loss_reasons(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,board_id int not null references crm_boards on delete cascade,name text not null,active bool not null default true,system bool not null default false);
create table crm_cards(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,board_id int not null references crm_boards,stage_id int not null references crm_stages,contact_id int references contacts,conversation_id int references conversations,title text not null,description text not null default '',amount numeric not null default 0 check(amount>=0),owner_id int references users,created_by int references users,status text not null default 'open' check(status in ('open','won','lost','archived','deleted')),previous_status text,previous_stage_id int references crm_stages,loss_reason text,due_at timestamptz,labels int[] not null default '{}',custom_fields jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),activity_at timestamptz not null default now(),closed_at timestamptz,version int not null default 1);
create table crm_events(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,board_id int not null references crm_boards,card_id int references crm_cards,actor_id int references users,type text not null,data jsonb not null default '{}',at timestamptz not null default now());
create table crm_notes(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,card_id int not null references crm_cards,author_id int references users,body text not null,at timestamptz default now());
create table crm_goals(tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,board_id int references crm_boards,user_id int not null default 0,month date not null,amount numeric not null check(amount>=0),primary key(tenant_id,board_id,user_id,month));
create table action_confirmations(id uuid primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,user_id int references users,action jsonb not null,code_hash text not null,expires_at timestamptz not null,attempts int not null default 0,used bool not null default false,channel text not null,destination text not null,delivery text not null default 'pending',created_at timestamptz default now());
create index service_events_conversation on service_events(tenant_id,conversation_id,at);
create index crm_cards_board on crm_cards(tenant_id,board_id,status,activity_at);
create index crm_events_board on crm_events(tenant_id,board_id,at);
do $$ declare r record;begin for r in select * from (values
 ('service_events','conversations,conversation_id,users,actor_id,teams,team_id'),('labels',''),('field_definitions',''),('contact_notes','contacts,contact_id,conversations,conversation_id,users,author_id'),('media_assets','users,owner_id'),
 ('crm_boards','users,created_by'),('crm_stages','crm_boards,board_id'),('crm_loss_reasons','crm_boards,board_id'),('crm_cards','crm_boards,board_id,crm_stages,stage_id,contacts,contact_id,conversations,conversation_id,users,owner_id,users,created_by,crm_stages,previous_stage_id'),('crm_events','crm_boards,board_id,crm_cards,card_id,users,actor_id'),('crm_notes','crm_cards,card_id,users,author_id'),('crm_goals','crm_boards,board_id'),('action_confirmations','users,user_id')) v(t,a) loop
 execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);
 execute format($f$create policy tenant_iso on %I using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int)$f$,r.t);
 if r.a<>'' then execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.a,',')) x));end if;
 end loop;end $$;
create function log_service_message() returns trigger language plpgsql as $$ begin
 insert into service_events(conversation_id,actor_id,team_id,type,data,at) select new.conversation_id,new.author_id,c.team_id,case when new.dir='in' then 'received' when new.dir='int' then 'note' when new.ai then 'automatic_reply' else 'human_reply' end,jsonb_build_object('message_id',new.id,'kind',new.kind),new.at from conversations c where c.id=new.conversation_id;
 update crm_cards set activity_at=now() where conversation_id=new.conversation_id and status='open';return new;end $$;
create trigger log_service_message after insert on messages for each row execute function log_service_message();
create function log_service_control() returns trigger language plpgsql as $$ begin
 if TG_OP='INSERT' then insert into service_events(conversation_id,team_id,type) values(new.id,new.team_id,'opened');
 elsif (new.assignee_id,new.team_id,new.automation_mode,new.status) is distinct from (old.assignee_id,old.team_id,old.automation_mode,old.status) then insert into service_events(conversation_id,actor_id,team_id,type,data) values(new.id,nullif(current_setting('app.actor',true),'')::int,new.team_id,'control',jsonb_build_object('from_user',old.assignee_id,'to_user',new.assignee_id,'from_team',old.team_id,'to_team',new.team_id,'mode',new.automation_mode,'status',new.status));end if;return new;end $$;
create trigger log_service_control after insert or update on conversations for each row execute function log_service_control();

update conversations c set created_at=coalesce((select min(at) from messages m where m.conversation_id=c.id),c.last_at,c.created_at);
insert into service_events(conversation_id,actor_id,team_id,type,data,at) select m.conversation_id,m.author_id,c.team_id,case when m.dir='in' then 'received' when m.dir='int' then 'note' when m.ai then 'automatic_reply' else 'human_reply' end,jsonb_build_object('message_id',m.id,'kind',m.kind,'backfilled',true),m.at from messages m join conversations c on c.id=m.conversation_id;
